'use strict';
// Writes js/icon-bounds.js: for every icons/*.png the box of its non-transparent
// pixels, so a visit mark can hug the drawn part of an image that has transparent
// margins. Run with: node tools/icon-bounds.js   (plain Node, no dependencies)
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const ICONS = path.join(__dirname, '..', 'icons');
const OUT = path.join(__dirname, '..', 'js', 'icon-bounds.js');

function decode(buf) {
	let pos = 8;
	let width = 0, height = 0, depth = 0, type = 0, interlace = 0;
	const idat = [];
	let palette = null, trns = null;
	while (pos < buf.length) {
		const len = buf.readUInt32BE(pos);
		const chunk = buf.toString('ascii', pos + 4, pos + 8);
		const data = buf.subarray(pos + 8, pos + 8 + len);
		if (chunk === 'IHDR') { width = data.readUInt32BE(0); height = data.readUInt32BE(4); depth = data[8]; type = data[9]; interlace = data[12]; }
		else if (chunk === 'PLTE') palette = data;
		else if (chunk === 'tRNS') trns = data;
		else if (chunk === 'IDAT') idat.push(data);
		else if (chunk === 'IEND') break;
		pos += 12 + len;
	}
	if (depth !== 8 || interlace !== 0) throw new Error(`only 8-bit non-interlaced PNGs are supported (depth ${depth}, interlace ${interlace})`);
	const channels = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 }[type];
	const stride = width * channels;
	const raw = zlib.inflateSync(Buffer.concat(idat));
	const px = Buffer.alloc(stride * height);
	for (let y = 0; y < height; y++) {
		const filter = raw[y * (stride + 1)];
		const inRow = y * (stride + 1) + 1, outRow = y * stride, prevRow = (y - 1) * stride;
		for (let x = 0; x < stride; x++) {
			const a = x >= channels ? px[outRow + x - channels] : 0;
			const b = y > 0 ? px[prevRow + x] : 0;
			const c = x >= channels && y > 0 ? px[prevRow + x - channels] : 0;
			const v = raw[inRow + x];
			let p;
			switch (filter) {
				case 0: p = v; break;
				case 1: p = v + a; break;
				case 2: p = v + b; break;
				case 3: p = v + ((a + b) >> 1); break;
				case 4: { const pa = Math.abs(b - c), pb = Math.abs(a - c), pc = Math.abs(a + b - 2 * c); p = v + (pa <= pb && pa <= pc ? a : pb <= pc ? b : c); break; }
				default: throw new Error('bad filter ' + filter);
			}
			px[outRow + x] = p & 255;
		}
	}
	// alpha of pixel (x, y): true alpha channel, palette transparency, or opaque
	const alpha = (x, y) => {
		const i = (y * width + x) * channels;
		if (type === 6) return px[i + 3];
		if (type === 4) return px[i + 1];
		if (type === 3) return trns && px[i] < trns.length ? trns[px[i]] : 255;
		return 255;
	};
	return { width, height, type, hasTransparency: type === 6 || type === 4 || (type === 3 && !!trns), alpha };
}

const bounds = {};
for (const file of fs.readdirSync(ICONS).filter(f => f.endsWith('.png')).sort()) {
	const img = decode(fs.readFileSync(path.join(ICONS, file)));
	if (!img.hasTransparency) continue;
	let x0 = Infinity, y0 = Infinity, x1 = -1, y1 = -1;
	for (let y = 0; y < img.height; y++) for (let x = 0; x < img.width; x++) if (img.alpha(x, y) > 0) { if (x < x0) x0 = x; if (y < y0) y0 = y; if (x > x1) x1 = x; if (y > y1) y1 = y; }
	if (x1 < 0 || (x0 === 0 && y0 === 0 && x1 === img.width - 1 && y1 === img.height - 1)) continue;
	bounds[file] = [x0, y0, x1 - x0 + 1, y1 - y0 + 1];
}
const lines = [
	"'use strict';",
	'',
	'// Generated by tools/icon-bounds.js from icons/*.png: the box of the drawn (non-',
	'// transparent) pixels of each image as [x, y, width, height] in image pixels.',
	'// Images that are drawn edge to edge are left out.',
	'const IconBounds = {',
	...Object.entries(bounds).map(([file, box]) => `\t'${file}': [${box.join(', ')}],`),
	'};',
	'',
];
fs.writeFileSync(OUT, lines.join('\r\n'));
console.log(`wrote ${path.relative(process.cwd(), OUT)} with ${Object.keys(bounds).length} entries`);
for (const [file, box] of Object.entries(bounds)) console.log(`  ${file.padEnd(20)} ${box.join(',')}`);
